mapper.select:
SELECT t1.`device_id` `deviceId`,t1.`water_last_value` `waterLastValue`,t1.`electricity_last_value` `electricityLastValue` FROM `boiler_data` t1 INNER JOIN ( SELECT MAX(`collect_time`) AS `max_time`,`device_id` FROM `boiler_data` where
`collect_time` >= #{param.stTime}
GROUP BY `device_id` ) t2 ON t1.`device_id` = t2.`device_id` AND t1.`collect_time` = t2.max_time where
t1.`collect_time` >= #{param.stTime}

SELECT
    COALESCE(SUM( `water_value` ),0)
FROM
    `boiler_data`
    where

     `collect_time` >= #{st}


    and `collect_time` <= #{et}


    and `device_id` in

        #{id}

SELECT
    COALESCE(SUM( `electricity_value` ),0)
FROM
`boiler_data`
where

    `collect_time` >= #{st}


    and `collect_time` <= #{et}


    and `device_id` in

        #{id}

SELECT COALESCE( AVG( a.`temperature` ), 0 ) `dataValue`, b.`device_name` `deviceName`, DATE_FORMAT( a.`collect_time`, ${dateFormat} ) `timeFlag` FROM `boiler_data` a LEFT JOIN `security_device` b ON a.`device_id` = b.`device_id` WHERE b.`application_code` = 'BOLIER'
and a.`collect_time` >= #{st}
and a.`collect_time` <= #{et}
and a.`device_id` in
#{id}
GROUP BY b.`device_name`, DATE_FORMAT( a.`collect_time`, ${dateFormat})

SELECT COALESCE( AVG( a.`temperature` ), 0 ) `dataValue`, b.`device_name` `deviceName`, DATE_FORMAT( a.`collect_time`, ${dateFormat} ) `timeFlag` FROM `boiler_data` a LEFT JOIN `security_device` b ON a.`device_id` = b.`device_id` WHERE b.`application_code` = 'BOLIER'
and a.`collect_time` >= #{st}
and a.`collect_time` <= #{et}
and a.`device_id` in
#{id}
GROUP BY b.`device_name`, DATE_FORMAT( a.`collect_time`, ${dateFormat})

SELECT COALESCE( AVG( a.`temperature` ), 0 ) `dataValue`, b.`device_name` `deviceName`, to_char( a.`collect_time`, ${dateFormat} ) `timeFlag` FROM `boiler_data` a LEFT JOIN `security_device` b ON a.`device_id` = b.`device_id` WHERE b.`application_code` = 'BOLIER'
and a.`collect_time` >= #{st}
and a.`collect_time` <= #{et}
and a.`device_id` in
#{id}
GROUP BY b.`device_name`, to_char( a.`collect_time`, ${dateFormat})

SELECT COALESCE( sum( a.`electricity_value` ), 0 ) `dataValue`, b.`device_name` `deviceName`, DATE_FORMAT( a.`collect_time`, ${dateFormat} ) `timeFlag` FROM `boiler_data` a LEFT JOIN `security_device` b ON a.`device_id` = b.`device_id` WHERE b.`application_code` = 'BOLIER'
and a.`collect_time` >= #{st}
and a.`collect_time` <= #{et}
and a.`device_id` in
#{id}
GROUP BY b.`device_name`, DATE_FORMAT( a.`collect_time`, ${dateFormat})

SELECT COALESCE( sum( a.`electricity_value` ), 0 ) `dataValue`, b.`device_name` `deviceName`, DATE_FORMAT( a.`collect_time`, ${dateFormat} ) `timeFlag` FROM `boiler_data` a LEFT JOIN `security_device` b ON a.`device_id` = b.`device_id` WHERE b.`application_code` = 'BOLIER'
and a.`collect_time` >= #{st}
and a.`collect_time` <= #{et}
and a.`device_id` in
#{id}
GROUP BY b.`device_name`, DATE_FORMAT( a.`collect_time`, ${dateFormat})

SELECT COALESCE( sum( a.`electricity_value` ), 0 ) `dataValue`, b.`device_name` `deviceName`, to_char( a.`collect_time`, ${dateFormat} ) `timeFlag` FROM `boiler_data` a LEFT JOIN `security_device` b ON a.`device_id` = b.`device_id` WHERE b.`application_code` = 'BOLIER'
and a.`collect_time` >= #{st}
and a.`collect_time` <= #{et}
and a.`device_id` in
#{id}
GROUP BY b.`device_name`, to_char( a.`collect_time`, ${dateFormat})

SELECT a.`water_value` `waterValue`, a.`temperature` `temperature`, a.`electricity_value` `electricityValue`, a.`collect_time` `collectTime`, b.`device_name` `deviceName`, b.`area_name` `areaName` FROM `boiler_data` a LEFT JOIN `security_device` b ON a.`device_id` = b.`device_id` where b.`application_code` = 'BOLIER'
and a.`collect_time` >= #{param.period.begin}
and a.`collect_time` <= #{param.period.end}
and b.`device_name` like concat('%',#{param.keyword},'%')
